def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    urgent_opp_count = 0
    rich_aggressive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opp_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 80 and opp.get('budget', 0) >= 200:
                    rich_aggressive += 1

    if not alive_opps:
        return float(min(budget, 18.0))

    slots = max(1, int(supply // WATER_REQ))
    tight_supply = slots <= 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 1

    if tight_supply:
        danger += 2
    if urgent_opp_count >= 2:
        danger += 1
    if day >= 8:
        danger += 1

    if danger >= 5:
        bid = max(78.0, highest_prev + 2.5)
    elif danger >= 3:
        bid = max(58.0, min(88.0, avg_prev * 0.78 + 6.0))
    else:
        if rich_aggressive >= 2 or highest_prev >= 90:
            bid = 16.0 if not tight_supply else 24.0
        elif highest_prev >= 70:
            bid = 22.0 if not tight_supply else 32.0
        else:
            bid = 28.0 if tight_supply else 18.0

    if budget < DAILY_SALARY * 0.8 and danger < 3:
        bid = min(bid, 24.0)

    if hp <= 2 or no_water >= 2:
        bid = max(bid, 84.0)

    if day == 10 and hp <= 4:
        bid = max(bid, 90.0)

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace (immediate reaction only)
    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Default target: secure water with a moderate bid; avoid Cindy-style overbidding
    # Supply affects how many bidders might need to be competitive.
    supply_factor = 1.0
    if supply <= float(MIN_SUPPLY):
        supply_factor = 1.15
    elif supply >= float(MAX_SUPPLY):
        supply_factor = 0.95

    # If we are in danger (multiple no-water days), bid more aggressively.
    if my_hp <= 2 or my_no_water_days >= 3:
        base = DAILY_SALARY * 0.95
    elif my_hp <= 4 or my_no_water_days >= 2:
        base = DAILY_SALARY * 0.75
    else:
        base = DAILY_SALARY * 0.55

    # Undercut strategy vs yesterday extremes: if someone overbid badly, don't match.
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        # If there was a very high bidder (likely Cindy), stay below that by a margin.
        if max_prev >= DAILY_SALARY * 1.25:
            # Use a cap just under the extreme to avoid price war.
            base = min(base * supply_factor, max(DAILY_SALARY * 0.65, max_prev - 25.0))
        else:
            # Otherwise, bid around the upper-middle of yesterday bids.
            sorted_b = sorted(yesterday_bids)
            idx = int(len(sorted_b) * 0.7) - 1
            if idx < 0:
                idx = 0
            mid_prev = sorted_b[idx]
            base = min(base * supply_factor, max(mid_prev + 1.0, base))

    # Convert bid to a feasible range
    bid = float(base)
    if bid > my_budget:
        bid = my_budget

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    # Small day-to-day jitter to avoid ties/predictability
    # (Deterministic, no randomness.)
    jitter = ((day % 5) - 2) * 0.8
    bid = bid + float(jitter)

    if bid > my_budget:
        bid = my_budget
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.55

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.8
    elif my_status['hp'] <= 6 and day_context['day'] > EPISODE_DAYS / 2:
        base_bid = DAILY_SALARY * 0.75

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2 and my_status['hp'] <= 5:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)
    elif remaining_days <= 3 and my_status['hp'] <= 3:
        base_bid = max(base_bid, DAILY_SALARY * 0.95)

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] > 5:
                base_bid = max(base_bid, highest_prev_bid * 0.95)
            else:
                base_bid = max(base_bid, highest_prev_bid + 5)
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            base_bid = max(base_bid, highest_prev_bid * 1.05)
        else:
            base_bid = max(base_bid, highest_prev_bid + 1)

    if day_context['supply'] <= 17:
        base_bid += 5

    final_bid = min(my_status['budget'], base_bid)

    if final_bid < DAILY_SALARY * 0.1 and my_status['budget'] > 0:
        final_bid = min(my_status['budget'], DAILY_SALARY * 0.1)

    return final_bid

def get_bid(day_context, my_status, opponents_status):
